import{_ as o,o as i,c as s,a5 as a}from"./chunks/framework.DrDMl0tG.js";const u=JSON.parse('{"title":"Changelog: v2.7","description":"","frontmatter":{},"headers":[],"relativePath":"sections/changelog/v2.7.md","filePath":"sections/changelog/v2.7.md"}'),t={name:"sections/changelog/v2.7.md"};function r(l,e,n,c,d,p){return i(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="changelog-v2-7" tabindex="-1">Changelog: v2.7 <a class="header-anchor" href="#changelog-v2-7" aria-label="Permalink to &quot;Changelog: v2.7&quot;">​</a></h1><h2 id="v2-7-0-2026-09-28" tabindex="-1">v2.7.0 (2026-09-28) <a class="header-anchor" href="#v2-7-0-2026-09-28" aria-label="Permalink to &quot;v2.7.0 (2026-09-28)&quot;">​</a></h2><p><strong>Pin joints and closed loops</strong></p><ul><li>Much faster closed-loop solves: Minitaur step 16.7 µs → 8.0 µs, solver sweeps 31 → 2.1 per step; pin rows warm-started.</li><li>Exact pin/self-contact inverse mass (sparse J·M⁻¹·Jᵀ).</li><li>Correct pin Jacobians (own anchor per body, fixed world basis, floating-base rotation columns kept); robust 3×3 effective mass for planar/redundant pins; 30% per-step position correction.</li><li>Sleeping objects no longer apply stale constraints; pins stay closed under mouse-drag and wire forces.</li><li>New Cassie closed-loop URDF (<code>res/cassie/cassie_v4_raisim.urdf</code>).</li></ul><p><strong>Granular and deformable</strong></p><ul><li>Faster granular contacts (contact-history index, incremental grid, cheaper pair rejection): 1,536-grain pool 0.71 s → 0.55 s.</li><li>Opt-in <code>GranularPoolSleepController</code> (1.09–1.34× faster settled pools).</li><li>Removing particles remaps/drops tendons attached to them (fixed out-of-bounds write).</li><li>Deformable particle pairs use a sparse grid.</li></ul><p><strong>Assets</strong></p><ul><li><code>.rasset</code> descriptor (<code>raisim::Rasset::load</code>/<code>save</code>/<code>instantiate</code>/<code>addStaticColliders</code>); the TCP viewer resolves <code>.rasset</code> visuals.</li></ul><p><strong>Contacts</strong></p><ul><li>Fixed: primitives falling through rotated meshes, box–cylinder rim contacts, parallel capsules, tilted cylinder on plane, plane–mesh normal flip, NaN AABBs in SAP, heightmap depth 5–300× too deep, frictionless contacts, static–static problems, pinned deformable normals, swept CCD stopping mid-air.</li><li><code>Contact::getSolverPosition()</code>.</li></ul><p><strong>ArticulatedSystem</strong></p><ul><li>Fixed: sensors on movable links aborting, <code>Child</code> constructor options and root pose, <code>getAngularMomentum</code>, <code>SparseJacobian</code> resize, 0-DOF <code>getInverseMassMatrix</code>, fixed-base <code>setBasePos</code> COM, <code>getNonlinearities</code> overwriting frame accelerations, RNE constraint-force lever arm, spherical effort limit, prismatic <code>ref</code>.</li><li><code>setJointLimits</code>/<code>setJointVelocityLimits</code> validate sizes; <code>getFrameAcceleration</code> documented as specific force.</li></ul><p><strong>Loaders</strong></p><ul><li>MJCF: <code>&lt;freejoint/&gt;</code>, multi-joint bodies, rotated joint frames, quaternion/<code>xyaxes</code>/<code>zaxis</code> validation, extrinsic uppercase Euler.</li><li>XML: <code>collision_group</code> hang, templated robots survive save/reload, duplicate names on export.</li><li>USD: collision meshes through symlinked directories.</li></ul><p><strong>RaisimServer</strong></p><ul><li>Fixed: send-buffer overflow on large scenes, SIGPIPE on viewer close, short polylines exiting, dangling <code>focusOn</code>, tag 0 matching, sensor exchange dropping clients, invalid wires; mouse force stays on the same body point.</li><li>License activation is thread-safe (one <code>World</code> per thread).</li></ul><p><strong>rayrai</strong></p><ul><li><strong>Breaking:</strong> <code>glm::vec4</code> orientations are (w, x, y, z) everywhere.</li><li>Glass: <code>Material::glass()</code>, progressive path-traced geometry refraction, optional Vulkan ray-query backend; <code>rayrai_glass</code>, <code>rayrai_nested_glass</code>, <code>rayrai_multiple_lights</code> examples.</li><li>Foliage: automatic mesh LOD, async preparation, GPU/Hi-Z occlusion, batching, depth prepasses, wind, BC7; dense-forest examples.</li><li>Lighting: baked irradiance and sky-visibility grids, soft directional shadows, deep parallax, linear HDR; range-culled local lights.</li><li>Multithreaded/multi-window rendering; lower frame overhead.</li><li>Fixes: batch upload cache, upscale blit, camera frame cache, additional-light shadows on ≤32 texture units, sampler/cascade unit clash, foliage submesh offsets, LOD on line/point meshes, point size, weather resets, lidar angle grid, depth linearization.</li></ul><p><strong>TCP viewer</strong></p><ul><li>Filmic and AgX tone mapping; auto-connect to a local server.</li><li>Fixes: crash on disconnect with frustum shown, use-after-free on removal, unique recording names, atomic settings, live resource-dir edits, stale replay geometry.</li></ul><p><strong>Build</strong></p><ul><li>Windows short build dirs and <code>raisim-imported-config.cmake</code>; Linux shader-manifest check; Vulkan headers and SPIR-V are vendored; CMake verifies the source manifest without Python.</li></ul>',22)])])}const m=o(t,[["render",r]]);export{u as __pageData,m as default};
